import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.DzNHXt93.js";const p=JSON.parse('{"title":"Content-addressed artifact transport (artifacts.takoform.com/v1alpha1)","description":"","frontmatter":{},"headers":[],"relativePath":"spec/artifact-transport/index.md","filePath":"spec/artifact-transport/index.md"}'),s={name:"spec/artifact-transport/index.md"};function d(n,e,r,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="content-addressed-artifact-transport-artifacts-takoform-com-v1alpha1" tabindex="-1">Content-addressed artifact transport (artifacts.takoform.com/v1alpha1) <a class="header-anchor" href="#content-addressed-artifact-transport-artifacts-takoform-com-v1alpha1" aria-label="Permalink to &quot;Content-addressed artifact transport (artifacts.takoform.com/v1alpha1)&quot;">​</a></h1><p>The v1alpha3 lane replaces external credential-free artifact URLs with a content-addressed upload API owned by the host (<a href="./../decisions/0012-artifacts-use-content-addressed-upload.html">decision 0012</a>). Desired state references only immutable manifest digests; raw code bytes, upload endpoints, and transport details never enter client state.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p>Relative to the discovered <code>endpoints.api</code> base (<code>/apis/forms.takoform.com/v1alpha3</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST   {api}/artifacts/uploads                      start an upload; body carries the manifest</span></span>
<span class="line"><span>PUT    {api}/artifacts/uploads/{uploadId}/blobs/{sha256}   upload one missing blob</span></span>
<span class="line"><span>POST   {api}/artifacts/uploads/{uploadId}/commit    verify and commit the manifest</span></span>
<span class="line"><span>GET    {api}/artifacts/{manifestDigest}             read a committed manifest</span></span>
<span class="line"><span>HEAD   {api}/artifacts/blobs/{sha256}               probe blob presence</span></span>
<span class="line"><span>DELETE {api}/artifacts/uploads/{uploadId}           abandon an incomplete upload</span></span></code></pre></div><h2 id="upload-flow" tabindex="-1">Upload flow <a class="header-anchor" href="#upload-flow" aria-label="Permalink to &quot;Upload flow&quot;">​</a></h2><ol><li>The client computes the SHA-256 of every local file and builds a typed manifest (<a href="/schemas/artifacts/v1alpha1/artifact-manifest.schema.json"><code>artifact-manifest-v1alpha1.schema.json</code></a>).</li><li><code>POST /artifacts/uploads</code> submits the manifest. The response is an <code>artifactUploadStatus</code> naming the <code>uploadId</code> and the digests of blobs the host does not already hold.</li><li>The client uploads only the missing blobs. Each <code>PUT</code> body is the exact blob; the host verifies its size and digest on receipt.</li><li><code>POST .../commit</code> re-verifies the manifest and every blob against it (size, digest, media type, path grammar, per-kind shape) and returns the immutable <code>manifestDigest</code>: the RFC 8785 canonical digest of the manifest bytes.</li><li>Desired state (for example a <code>WorkerBundle</code> revision) references the manifest digest only.</li></ol><p>Uploads are resumable: repeating step 2 with the same manifest returns the still-missing blob set, and committing an already-committed manifest is idempotent and returns the same digest. An abandoned <code>uploadId</code> may be garbage-collected by the host; committed manifests and their blobs are retained while any resource references them.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>A host MUST reject, before commit:</p><ul><li>duplicate module or file names;</li><li>absolute paths, <code>..</code> or <code>.</code> segments, backslashes, NUL, invalid UTF-8;</li><li>media types outside the manifest kind&#39;s closed set;</li><li>size or digest mismatches between manifest and received bytes;</li><li>file-count or total-size overruns of the host&#39;s published limits;</li><li>a <code>WorkerBundle</code> whose <code>mainModule</code> is not listed in <code>modules</code>;</li><li>a <code>WorkerBundle</code> whose <code>mainModule</code> names an auxiliary module;</li><li>a source map whose target module is absent;</li><li>archive bombs — archives are transport only and never semantic identity.</li></ul><p>Rejections use <code>artifact_invalid</code> (400); a commit referencing a blob that was never uploaded uses <code>artifact_missing</code> (404).</p><p>Every rule above is re-verified at commit, because commit is the step that mints an immutable identity. A host MUST NOT rely on having checked the manifest only when the upload started.</p><h2 id="module-media-types-loadable-and-auxiliary" tabindex="-1">Module media types: loadable and auxiliary <a class="header-anchor" href="#module-media-types-loadable-and-auxiliary" aria-label="Permalink to &quot;Module media types: loadable and auxiliary&quot;">​</a></h2><p>A <code>WorkerBundle</code> manifest admits exactly five module media types, and they divide into two classes by what the module graph does with them:</p><table tabindex="0"><thead><tr><th>Class</th><th>Media type</th><th>The importing module receives</th></tr></thead><tbody><tr><td>loadable</td><td><code>application/javascript+module</code></td><td>an ES module</td></tr><tr><td>loadable</td><td><code>text/plain</code></td><td>the decoded UTF-8 text</td></tr><tr><td>loadable</td><td><code>application/octet-stream</code></td><td>an <code>ArrayBuffer</code></td></tr><tr><td>loadable</td><td><code>application/wasm</code></td><td>a compiled <code>WebAssembly.Module</code>, never an instance</td></tr><tr><td>auxiliary</td><td><code>application/source-map+json</code></td><td>nothing: it is never imported</td></tr></tbody></table><p><strong>Loadable</strong> is the set the module graph may import, and it is exactly the set <code>worker.runtime@1.0.0</code>&#39;s <code>loadModule</code> operation states (<a href="./../decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>). <strong>Auxiliary</strong> is what a bundle may carry without ever linking it: today, source-map evidence about another module. A host MUST refuse an auxiliary module as a bundle&#39;s <code>mainModule</code> (<code>artifact_invalid</code>, 400), a runtime MUST fail an import resolving to one (<code>unsupported_media_type</code>), and neither may treat the module&#39;s mere presence in <code>modules</code> as an error — carrying it is the whole point.</p><p><code>application/json</code> is not supported in this ABI version. The published manifest enum never admitted it, so a runtime that loaded one would promise a module no conforming bundle can carry.</p><p>The published manifest schema states the union and cannot state the split: its <code>modules[].mediaType</code> enum lists all five, and nothing in JSON Schema relates <code>mainModule</code> to the media type of the module it names. The split is therefore enforced by the host, by the authoring client, and by the required conformance check <code>bundle-main-module-is-loadable</code> (<a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>). The set has one source of truth, <code>internal/currentformmodel</code>, which the runtime contract, the host validator, and the provider&#39;s authoring allowlist all read; a drift gate holds it to the published enum.</p><h2 id="per-kind-exclusivity" tabindex="-1">Per-kind exclusivity <a class="header-anchor" href="#per-kind-exclusivity" aria-label="Permalink to &quot;Per-kind exclusivity&quot;">​</a></h2><p>A manifest kind decides which payload members the document may carry, and it is normative:</p><ul><li>a <code>WorkerBundle</code> manifest carries <code>mainModule</code> and <code>modules</code> and MUST NOT carry <code>files</code>;</li><li>a <code>StaticAssetBundle</code> or <code>MigrationBundle</code> manifest carries <code>files</code> and MUST NOT carry <code>mainModule</code> or <code>modules</code>.</li></ul><p>A manifest carrying both shapes has two meanings, which a content-addressed identity must never have; violations are <code>artifact_invalid</code> (400). The published manifest schema is the structural minimum for this document and declares all three members for every kind, so this closure is enforced by the host and proved by a required conformance check rather than by the schema (<a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>).</p><h2 id="referencing-a-manifest-from-desired-state" tabindex="-1">Referencing a manifest from desired state <a class="header-anchor" href="#referencing-a-manifest-from-desired-state" aria-label="Permalink to &quot;Referencing a manifest from desired state&quot;">​</a></h2><p>A bundle-shaped revision resource carries the manifest digest as its whole desired state; the manifest, not the resource, describes the bytes. Before any mutation — apply and import alike — a host MUST resolve the referenced manifest and fail closed when the digest names no committed manifest the caller&#39;s tenant holds (<code>artifact_missing</code>, 404), when the stored document does not canonicalize to the referenced digest, when its <code>kind</code> is not the kind the Form requires, or when it violates any rule above (<code>artifact_invalid</code>, 400).</p><p>Resolving a manifest on behalf of a request is subject to the same per-tenant holding rule as reading one (<a href="./../decisions/0018-the-host-api-is-deployable-behind-ordinary-infrastructure.html">decision 0018</a>): a digest is a name for bytes and entitles nobody to them, whether it is read from <code>GET {api}/artifacts/{manifestDigest}</code> or used as desired state. A manifest another tenant committed is therefore answered exactly as an uncommitted digest is — the same <code>artifact_missing</code>, indistinguishable from &quot;no such manifest&quot; — and that answer is re-derived when an accepted <code>202</code> commits, not only when the mutation was accepted. Holding is the tenant&#39;s, not one principal&#39;s, so the ordinary pipeline in which one principal uploads a bundle and another references it is unaffected.</p><p>A committed manifest and its blobs MUST stay readable while any resource references the manifest: abandoning an unrelated upload session, or collecting staged blobs, MUST NOT make a referenced artifact unresolvable.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li>The manifest is data-only: no credentials, endpoints, or host identities.</li><li>A manifest digest is an immutable identity; the same digest MUST resolve to the same canonical manifest bytes on every conforming host that holds it.</li><li>Blob storage, deduplication, and retention policy are host-owned.</li><li>The frozen v1alpha1/v1alpha2 lanes keep their credential-free URL contract (<a href="./../decisions/0002-artifact-urls-are-credential-free-state.html">decision 0002</a>) unchanged.</li></ul>`,29)])])}const u=a(s,[["render",d]]);export{p as __pageData,u as default};
